import re
import os
from pathlib import Path
import glob

def task_func(directory_path: str, regex_pattern: str = r'\(.+?\)|\w') -> dict:
    directory = Path(directory_path)

    if not directory.exists():
        raise FileNotFoundError(f"Directory does not exist: {directory_path}")
    if not directory.is_dir():
        raise NotADirectoryError(f"Not a directory: {directory_path}")

    pattern = re.compile(regex_pattern)
    result = {}

    for file_name in sorted(glob.glob(str(directory / "*"))):
        file_path = Path(file_name)
        if not file_path.is_file() or file_path.suffix.lower() != ".txt":
            continue

        try:
            content = file_path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue

        result[file_path.name] = pattern.findall(content)

    return result
